    def __init__(self):
        self.rolls = []
        self.current_frame = 1
        self.frame_rolls = []
        self.bonus_rolls = []
        self.frame_score = 0
        self.total_score = 0

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise ValueError("pins must be between 0 and 10")
        if self.current_frame > 10:
            raise ValueError("Cannot roll after 10 frames")
        if pins < 0 or pins > 10:
            raise ValueError("pins must be between 0 and 10")
        self.rolls.append(pins)
        self.frame_rolls.append(pins)
        if pins == 10:  # Strike
            self.bonus_rolls.append(pins)
        elif len(self.frame_rolls) == 2 and sum(self.frame_rolls) == 10:  # Spare
            self.bonus_rolls.append(pins)
        else:
            self.current_frame += 1
            self.frame_rolls = []

    def score(self):
        pass

