class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.current_frame = 1
        self.frame_rolls = []
        self.bonus_rolls = []
        self.total_score = 0

    def roll(self, pins):
        if self.current_frame > 10:
            raise ValueError("Cannot roll after 10 frames")
        if pins < 0 or pins > 10:
            raise ValueError("pins must be between 0 and 10")
        self.rolls.append(pins)
        self.frame_rolls.append(pins)
        if pins == 10:  # Strike
            self.bonus_rolls.append(pins)
        elif len(self.frame_rolls) == 2 and sum(self.frame_rolls) == 10:  # Spare
            self.bonus_rolls.append(pins)
        else:
            if self.current_frame == 10:
                raise ValueError("Cannot roll after 10th frame")
            self.current_frame += 1
            self.frame_rolls = []

    def score(self):
        total = 0
        frame = 0
        while frame < 10:
            if self.rolls[frame] == 10:  # Strike
                total += 10 + self.rolls[frame+1] + (self.rolls[frame+2] if frame+2 < len(self.rolls) else 0)
                frame += 1
            else:
                if frame + 1 >= len(self.rolls):
                    raise ValueError("Incomplete game")
                frame_score = self.rolls[frame] + self.rolls[frame+1]
                if frame_score == 10:  # Spare
                    total += 10 + (self.rolls[frame+2] if frame+2 < len(self.rolls) else 0)
                else:
                    total += frame_score
                frame += 2
        return total

